for(const r of extraRecipesV4){r.image=images[r.kind];recipes.push(r)}
const KEY='kamis-v2';let data;try{data=JSON.parse(localStorage.getItem(KEY))||{}}catch{data={}};
data={days:[0,1,2,3,4],budget:250,people:1,mode:'balanced',store:'Biedronka',meals:3,plan:null,saved:[],checked:{},excluded:[],...data};let page='home',step=0,filter='Wszystkie',search='',swapTarget=null;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data))}catch{alert('Nie udało się zapisać danych w pamięci urządzenia.')}}
function money(v){return v.toFixed(2).replace('.',',')+' zł'}function price(r){return r.ingredients.reduce((a,x)=>a+x[2],0)*data.people}function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function btn(text,fn,cls='btn'){return `<button class="${cls}" onclick="${fn}">${text}</button>`}
function setPage(p){page=p;step=0;swapTarget=null;render();window.scrollTo(0,0)}function goBack(){if(page==='wizard'&&step>0){stepBack();return}if(page==='recipes'&&swapTarget){setPage('home');return}setPage('home')}function tabs(){const names=[['home','🏠 Start'],['wizard','🗓️ Planuj'],['recipes','🍳 Przepisy'],['shopping','🛒 Zakupy'],['saved','💾 Zapisane'],['summary','📊 Podsumowanie']];$('tabs').innerHTML=names.map(([p,n])=>`<button class="tab ${page===p?'active':''}" onclick="setPage('${p}')">${n}</button>`).join('');$('count').textContent=recipes.length+' przepisów';$('backBtn').style.display=(page==='home'?'none':'inline-block')}
function card(r,actions=true){return `<article class="card"><img class="food" loading="lazy" src="${r.image}" alt="Zdjęcie poglądowe kategorii dania" onerror="this.style.display='none'"><div class="inside"><h3>${esc(r.name)}</h3><div class="muted">${r.meal} · ~${r.calories} kcal · ~${r.protein} g białka</div><div class="row" style="margin-top:10px"><span class="price">~${money(price(r))}</span>${btn('Przepis',`showRecipe(${r.id})`,'btn alt')}</div>${actions&&swapTarget!==null?btn('Wybierz to danie',`doSwap(${r.id})`):''}</div></article>`}
function showRecipe(id){const r=recipes.find(x=>x.id===id);$('dialogBody').innerHTML=`<h2>${esc(r.name)}</h2><img class="food" style="border-radius:14px;height:210px" src="${r.image}" alt="Zdjęcie poglądowe"><p class="muted">Zdjęcie poglądowe • ~${r.calories} kcal • ~${r.protein} g białka • cena porcji ~${money(price(r))}</p><h3>Składniki (${data.people} os.)</h3><ul>${r.ingredients.map(x=>`<li>${esc(x[0])} — ${x[1]*data.people} g / szt. (ilość orientacyjna)</li>`).join('')}</ul><h3>Przygotowanie</h3><ol>${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p class="notice">Wartości odżywcze i ceny są szacunkowe. Zdjęcie ilustruje typ potrawy, nie konkretny przepis. Mięso i ryby zawsze przygotuj do bezpiecznej temperatury.</p>`;$('recipeDialog').showModal()}
function home(){return `<section class="panel"><div class="step">TWÓJ PLANER POSIŁKÓW</div><h1>Co dziś dobrego, Kamiś? 🌿</h1><p>Zaplanuj wybrane dni, wybierz cel i budżet, a Kamiś dopasuje posiłki i przygotuje zakupy.</p><div class="actions">${btn('Ułóż nowy plan →',"setPage('wizard')")}${btn('Przeglądaj przepisy',"setPage('recipes')",'btn alt')}</div></section>${data.plan?planView():`<section class="panel"><h2>Nie masz jeszcze planu</h2><p class="muted">Wybierz dni i wygeneruj jadłospis. Możesz go później zapisać i przywrócić.</p></section>`}`}
function wizard(){const back=step>0?btn('← Wstecz','stepBack()','btn alt'):'';let content='';if(step===0)content=`<h2>Na które dni planujemy?</h2><p class="muted">Wybierz dowolne dni, nie musisz planować całego tygodnia.</p><div class="chips">${DAYS.map((d,i)=>`<button class="chip ${data.days.includes(i)?'selected':''}" onclick="toggleDay(${i})">${d}</button>`).join('')}</div>`;if(step===1)content=`<h2>Jaki jest Twój cel?</h2><div class="chips">${[['balanced','🍽️ Zbilansowane'],['low','🥗 Mało kalorii'],['protein','💪 Dużo białka'],['gym','🏋️ Siłownia']].map(([v,n])=>`<button class="chip ${data.mode===v?'selected':''}" onclick="chooseMode('${v}')">${n}</button>`).join('')}</div><p class="notice">Tryby są orientacyjnymi preferencjami doboru posiłków, nie indywidualną dietą ani planem redukcji masy ciała.</p>`;if(step===2)content=`<h2>Czego nie chcesz jeść?</h2><p class="muted">Zaznacz składniki, których chcesz unikać. Planer wykluczy dania z tymi składnikami.</p><div class="chips">${EXCLUSIONS.map(([id,label])=>`<button class="chip ${data.excluded.includes(id)?'selected':''}" onclick="toggleExclude('${id}')">${data.excluded.includes(id)?'✓ ':''}${label}</button>`).join('')}</div><p class="notice">Przy alergiach zawsze samodzielnie sprawdzaj etykiety produktów i ryzyko zanieczyszczenia krzyżowego.</p>`;if(step===3)content=`<h2>Budżet i liczba osób</h2><div class="field"><label>Budżet na wybrane dni (zł)</label><input type="number" min="1" max="100000" value="${data.budget}" onchange="setBudget(this.value)"></div><div class="field"><label>Liczba osób</label><input type="number" min="1" max="12" value="${data.people}" onchange="setPeople(this.value)"></div><div class="field"><label>Liczba posiłków dziennie</label><select onchange="data.meals=Number(this.value);persist()"><option value="2" ${data.meals===2?'selected':''}>2</option><option value="3" ${data.meals===3?'selected':''}>3</option></select></div>`;if(step===4)content=`<h2>Wybierz sklep</h2><div class="chips">${['Biedronka','Lidl','Auchan','Kaufland','Carrefour','Inny sklep'].map(s=>`<button class="chip ${data.store===s?'selected':''}" onclick="chooseStore('${s}')">${s}</button>`).join('')}</div><p class="notice">Marka sklepu jest etykietą listy zakupów. Nie pobieramy aktualnych cen ani stanów magazynowych. Koszty są orientacyjne i mogą różnić się między sklepami.</p>`;if(step===5)content=`<h2>Sprawdź ustawienia</h2><p><b>Dni:</b> ${data.days.map(i=>DAYS[i]).join(', ')}</p><p><b>Cel:</b> ${{balanced:'Zbilansowane',low:'Mało kalorii',protein:'Dużo białka',gym:'Siłownia'}[data.mode]}</p><p><b>Budżet:</b> ${money(data.budget)} · <b>Osób:</b> ${data.people} · <b>Posiłków:</b> ${data.meals}</p><p><b>Sklep:</b> ${data.store}</p><p class="notice">Planer dobiera dania z lokalnej bazy i próbuje zmieścić się w budżecie. Jeśli budżet jest zbyt niski, pokaże ostrzeżenie.</p>`;return `<section class="panel"><div class="step">KROK ${step+1} Z 6</div><div style="height:6px;background:#e6ede3;border-radius:6px;margin:12px 0 20px"><div style="height:6px;width:${(step+1)*100/6}%;background:#4e976b;border-radius:6px"></div></div>${content}<div class="actions">${back}${btn(step===5?'Generuj jadłospis ✨':'Zatwierdź i dalej →',step===5?'generate()':'stepNext()')}</div></section>`}
const EXCLUSIONS=[['pork','Wieprzowina'],['beef','Wołowina'],['chicken','Drób'],['fish','Ryby'],['nuts','Orzechy'],['dairy','Nabiał'],['eggs','Jajka'],['gluten','Gluten'],['soy','Soja'],['mushrooms','Grzyby']];
const ALLERGENS={nuts:/orzech|migdał|arachid|nerkow|pistacj/i,dairy:/mleko|jogurt|skyr|ser|twaróg|śmietan|mozzarella|cheddar|parmezan|masło|gouda/i,eggs:/jajk/i,gluten:/pieczywo|makaron|tortilla|bułka|pita|bajgiel|kuskus|bulgur|płatki|mąka/i,soy:/tofu|sos sojowy|soja/i,mushrooms:/pieczark|grzyb/i};
function allowed(r){const txt=r.ingredients.map(x=>x[0]).join(' ');return !(data.excluded||[]).some(k=>k==='pork'?(r.kind==='pork'||/wieprz|szynka|boczek|kiełbasa/i.test(txt)):k==='beef'?(r.kind==='beef'||/wołow/i.test(txt)):k==='chicken'?(r.kind==='chicken'||/kurczak|indyk|drobi/i.test(txt)):k==='fish'?(r.kind==='fish'||/ryb|łosoś|tuńczyk/i.test(txt)):ALLERGENS[k]?.test(txt))}
function toggleExclude(id){data.excluded=data.excluded.includes(id)?data.excluded.filter(x=>x!==id):[...data.excluded,id];persist();render()}
function toggleDay(i){data.days=data.days.includes(i)?data.days.filter(x=>x!==i):[...data.days,i].sort((a,b)=>a-b);persist();render()}function chooseMode(v){data.mode=v;persist();render()}function chooseStore(v){data.store=v;persist();render()}function setBudget(v){data.budget=Math.max(1,Number(v)||1);persist()}function setPeople(v){data.people=Math.max(1,Math.min(12,Number(v)||1));persist()}function stepNext(){if(step===0&&!data.days.length){alert('Wybierz przynajmniej jeden dzień.');return}step=Math.min(5,step+1);render()}function stepBack(){step=Math.max(0,step-1);render()}
function choose(meal,used,remaining){let pool=recipes.filter(r=>r.meal===meal&&!used.has(r.id)&&allowed(r));if(!pool.length)pool=recipes.filter(r=>r.meal===meal&&allowed(r));if(data.mode==='low')pool.sort((a,b)=>a.calories-b.calories);else if(data.mode==='protein'||data.mode==='gym')pool.sort((a,b)=>(b.protein/Math.max(1,b.calories))-(a.protein/Math.max(1,a.calories)));else pool.sort((a,b)=>a.calories-b.calories);let subset=pool.slice(0,Math.max(8,Math.floor(pool.length*.5)));let affordable=subset.filter(r=>price(r)<=remaining);if(affordable.length)subset=affordable;const r=subset[Math.floor(Math.random()*Math.min(subset.length,35))]||pool[0];used.add(r.id);return r.id}
function generate(){if(['Śniadanie','Obiad',...(data.meals===3?['Kolacja']:[])].some(m=>!recipes.some(r=>r.meal===m&&allowed(r)))){alert('Brak przepisów dla wybranych wykluczeń. Zmień ustawienia.');return}const used=new Set();let remaining=data.budget;const entries=[];for(const day of data.days){const meals=data.meals===2?['Śniadanie','Obiad']:['Śniadanie','Obiad','Kolacja'];const ids=meals.map(m=>{const id=choose(m,used,remaining/Math.max(1,(data.days.length-entries.length)*meals.length));remaining-=price(recipes[id]);return id});entries.push({day,ids})}data.plan={entries,created:new Date().toISOString(),mode:data.mode,store:data.store,people:data.people,budget:data.budget};data.checked={};persist();setPage('home')}
function planCost(){return data.plan?data.plan.entries.flatMap(e=>e.ids).reduce((a,id)=>a+price(recipes[id]),0):0}
function planView(){const total=planCost();return `<section class="panel"><div class="row"><h2>Twój jadłospis</h2><span class="pill">${data.plan.entries.length} dni</span></div><p class="muted">Szacowany koszt składników: <b>${money(total)}</b> / budżet ${money(data.plan.budget)} · ${data.plan.store}</p>${total>data.plan.budget?`<p class="notice">⚠️ Szacowany koszt przekracza budżet o ${money(total-data.plan.budget)}. Spróbuj zamienić dania na tańsze.</p>`:''}${data.plan.entries.map(e=>`<div class="day"><h3>${DAYS[e.day]}</h3>${e.ids.map((id,i)=>{const r=recipes[id];return `<div class="meal"><img loading="lazy" src="${r.image}" alt="Zdjęcie poglądowe"><div class="desc"><span class="small">${r.meal}</span><b>${esc(r.name)}</b><span class="small">~${r.calories} kcal · ${r.protein} g białka · ${money(price(r))}</span></div><div>${btn('Zmień',`swap(${e.day},${i})`,'btn alt')}${btn('Przepis',`showRecipe(${id})`,'btn alt')}</div></div>`}).join('')}</div>`).join('')}<div class="actions">${btn('💾 Zapisz ten plan','savePlan()')}${btn('🛒 Lista zakupów',"setPage('shopping')",'btn alt')}${btn('📊 Podsumowanie',"setPage('summary')",'btn alt')}${btn('Nowy plan',"setPage('wizard')",'btn alt')}</div></section>`}
function swap(day,index){swapTarget={day,index};filter=recipes[data.plan.entries.find(e=>e.day===day).ids[index]].meal;search='';setPage('recipes');swapTarget={day,index};render()}
function doSwap(id){const e=data.plan.entries.find(e=>e.day===swapTarget.day);e.ids[swapTarget.index]=id;persist();swapTarget=null;setPage('home')}
function recipesView(){let list=recipes.filter(r=>(filter==='Wszystkie'||r.meal===filter)&&allowed(r)&&r.name.toLowerCase().includes(search.toLowerCase()));return `<section class="panel"><h2>${swapTarget?'Wybierz zamiennik':'Baza przepisów'} (${list.length})</h2><p class="muted">Rozbudowane śniadania, obiady i kolacje. Zdjęcia są poglądowe i nie zawsze przedstawiają dokładny przepis.</p><input type="text" id="searchBox" placeholder="Szukaj dania lub składnika…" value="${esc(search)}" oninput="search=this.value;updateRecipes()"><div class="chips" style="margin:12px 0">${['Wszystkie','Śniadanie','Obiad','Kolacja'].map(f=>`<button class="chip ${filter===f?'selected':''}" onclick="filter='${f}';render()">${f}</button>`).join('')}</div><div id="recipeGrid" class="grid">${list.slice(0,48).map(r=>card(r)).join('')}</div>${list.length>48?`<div class="actions">${btn('Pokaż więcej ('+(list.length-48)+')','showAllRecipes()','btn alt')}</div>`:''}</section>`}
function updateRecipes(){const list=recipes.filter(r=>(filter==='Wszystkie'||r.meal===filter)&&allowed(r)&&r.name.toLowerCase().includes(search.toLowerCase()));$('recipeGrid').innerHTML=list.slice(0,48).map(r=>card(r)).join('')||'<p>Brak wyników.</p>'}function showAllRecipes(){$('recipeGrid').innerHTML=recipes.filter(r=>(filter==='Wszystkie'||r.meal===filter)&&allowed(r)&&r.name.toLowerCase().includes(search.toLowerCase())).map(r=>card(r)).join('')}
function shopping(){if(!data.plan)return `<section class="panel"><h2>Lista zakupów</h2><p>Najpierw wygeneruj jadłospis.</p>${btn('Zaplanuj',"setPage('wizard')")}</section>`;const map=new Map();for(const id of data.plan.entries.flatMap(e=>e.ids))for(const [name,qty,price] of recipes[id].ingredients){const v=map.get(name)||{qty:0,price:0};v.qty+=qty*data.people;v.price+=price*data.people;map.set(name,v)}const items=[...map].sort((a,b)=>a[0].localeCompare(b[0],'pl'));return `<section class="panel"><h2>🛒 Zakupy — ${data.plan.store}</h2><p class="muted">Łącznie ~${money(items.reduce((s,[,v])=>s+v.price,0))}. Orientacyjne ceny produktów, nie aktualne oferty sieci.</p>${items.map(([name,v])=>`<label class="shopping"><input type="checkbox" ${data.checked[name]?'checked':''} onchange="checkItem('${esc(name).replace(/'/g,'&#39;')}',this.checked)"><span class="item" style="${data.checked[name]?'text-decoration:line-through;opacity:.55':''}"><b>${esc(name)}</b><br><span class="small">~${Math.round(v.qty)} g / szt. (jednostka zależy od produktu)</span></span><span class="price">~${money(v.price)}</span></label>`).join('')}<div class="actions">${btn('Kopiuj listę','copyShopping()','btn alt')}${btn('Odznacz wszystko','clearChecks()','btn alt')}</div></section>`}
function checkItem(name,v){data.checked[name]=v;persist();render()}function clearChecks(){data.checked={};persist();render()}function copyShopping(){if(!data.plan)return;const map=new Map();for(const id of data.plan.entries.flatMap(e=>e.ids))for(const [n,q,p] of recipes[id].ingredients){const v=map.get(n)||[0,0];map.set(n,[v[0]+q*data.people,v[1]+p*data.people])}const t=`Kamiś — zakupy (${data.plan.store})\n`+[...map].map(([n,[q,p]])=>`${n}: ~${q} g/szt. — ${money(p)}`).join('\n');if(navigator.clipboard)navigator.clipboard.writeText(t).then(()=>alert('Skopiowano listę.')).catch(()=>prompt('Skopiuj listę:',t));else prompt('Skopiuj listę:',t)}
function savePlan(){if(!data.plan)return;const name=prompt('Nazwa zapisanego planu:',`Plan ${new Date().toLocaleDateString('pl-PL')}`);if(!name)return;data.saved.unshift({name:name.slice(0,70),plan:structuredClone(data.plan),date:new Date().toISOString()});persist();alert('Plan zapisany na tym urządzeniu!')}function restore(i){if(!confirm('Wczytać ten plan zamiast aktualnego?'))return;data.plan=structuredClone(data.saved[i].plan);data.people=data.plan.people;data.budget=data.plan.budget;data.store=data.plan.store;data.checked={};persist();setPage('home')}function removeSaved(i){if(confirm('Usunąć zapisany plan?')){data.saved.splice(i,1);persist();render()}}
function saved(){return `<section class="panel"><h2>💾 Zapisane jadłospisy</h2><p class="muted">Plany zapisują się w tej przeglądarce. Wyczyszczenie danych witryny może je usunąć.</p>${data.saved.length?data.saved.map((s,i)=>`<div class="shopping"><div class="item"><b>${esc(s.name)}</b><div class="small">${new Date(s.date).toLocaleDateString('pl-PL')} · ${s.plan.entries.length} dni · ${s.plan.store}</div></div>${btn('Wczytaj',`restore(${i})`)}${btn('Usuń',`removeSaved(${i})`,'btn danger')}</div>`).join(''):'<p>Nie masz jeszcze zapisanych planów.</p>'}<div class="actions">${btn('Eksportuj kopię danych','exportData()','btn alt')}<label class="btn alt">Importuj kopię <input type="file" accept="application/json" onchange="importData(event)" style="display:none"></label></div></section>`}
function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='kamis-kopia.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}async function importData(e){const f=e.target.files?.[0];if(!f)return;try{const obj=JSON.parse(await f.text());if(!Array.isArray(obj.saved)||!Array.isArray(obj.days))throw Error('Nieprawidłowy format');if(confirm('Zastąpić obecne dane kopią?')){data={...data,...obj};persist();render()}}catch{alert('Nie udało się wczytać kopii.')}}
function summary(){if(!data.plan)return '<section class="panel"><h2>Podsumowanie diety</h2><p>Najpierw wygeneruj plan.</p></section>';const rr=data.plan.entries.flatMap(e=>e.ids).map(id=>recipes.find(r=>r.id===id)).filter(Boolean);const sum=k=>rr.reduce((a,r)=>a+(r[k]||0),0);return `<section class="panel"><h2>📊 Podsumowanie jadłospisu</h2><p><b>${data.plan.entries.length} dni</b> · ${rr.length} posiłków · ${data.plan.people} os.</p><div class="grid"><div class="notice">Łącznie ~${sum('calories')} kcal</div><div class="notice">Łącznie ~${sum('protein')} g białka</div><div class="notice">Średnio dziennie ~${Math.round(sum('calories')/data.plan.entries.length)} kcal</div><div class="notice">Średnio dziennie ~${Math.round(sum('protein')/data.plan.entries.length)} g białka</div><div class="notice">Koszt ~${money(planCost())}</div><div class="notice">Budżet ${money(data.plan.budget)}</div></div><h3>Wykluczone składniki</h3><p>${(data.excluded||[]).map(x=>EXCLUSIONS.find(y=>y[0]===x)?.[1]).join(', ')||'Brak'}</p><p class="muted">Kalorie i białko są orientacyjne, dotyczą jednej porcji i nie stanowią indywidualnej porady dietetycznej. Sprawdzaj alergeny na etykietach.</p>${btn('← Wróć do planu',"setPage('home')",'btn alt')}</section>`}
function render(){tabs();$('content').innerHTML=page==='home'?home():page==='wizard'?wizard():page==='recipes'?recipesView():page==='shopping'?shopping():page==='summary'?summary():saved()}
render();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
